select "p".* from (select (CASE WHEN ("occurrences"."region" = ?) THEN "occurrences"."id" END) AS "id", (CASE WHEN ("occurrences"."region" = ?) THEN st_astext("occurrences"."geometry") END) AS "geometry" from "occurrences" where "occurrences"."region" = ? and ("occurrences"."geometry" && ST_MakeEnvelope(?, ?, ?, ?, 4326)) and ST_DWithin("occurrences"."geometry"::geography, ST_SetSRID(ST_MakePoint(?, ?), 4326)::geography, ?)) as "p" where "p"."geometry" is not null order by "p"."id" asc limit ?
